namespace RhoMicro.CodeAnalysis.Library.Text.Templating;
using System;

[Template(
    """"
    // <auto-generated>
    // This file was auto generated by the following tool: (:name:).
    {:
        if(includeLicenseDisclaimer)
        { 
    :}
    // The generator used to generate this file may be subject to a license.
    // This generated file is, however, not subject to that license.
    // Instead, it is subject to whatever licensing scheme is present in the project containing it.
    {:
        }
    :}
    // </auto-generated>
    {:
        if(includeWarningDisablePragma)
            (:"#pragma warning disable":)
    :}

    {:
        if(includeNullableEnableDirective)
            (:"#nullable enable":)
    :}

    {:
        if(!EmptyTemplate.Instance.Equals(body))
        {
    :}
    (:body:)
    {:
        }
    :}
    """", BodyParameterName = "body")]
#if RHOMICRO_CODEANALYSIS_UTILITYGENERATORS
[IncludeFile]
#endif
#if GENERATOR
[NonEquatable]
#endif
internal readonly partial struct GeneratedFileTemplate(
    String name, 
    Boolean includeLicenseDisclaimer = true,
    Boolean includeWarningDisablePragma = true,
    Boolean includeNullableEnableDirective = true);